INSERT INTO temp_seed_reviews VALUES
('54500700-0000-4000-9000-000000000001', '54500700-0000-4000-8000-000000000017', 'p-tourapi-126537', '북촌한옥마을', '여름엔 모기기피제 살짝 챙기면 좋음 ㅎㅎ 그래도 마루에 불어오는 바람이 에어컨 바람보다 훨씬 상쾌하네요.', '북적', 4, '["방문팁", "데이트", "산책"]'::jsonb, 37.579053, 126.986706, '2026-10-12T13:27:17Z'::timestamptz),
('54500700-0000-4000-9000-000000000002', '54500700-0000-4000-8000-000000000013', 'p-tourapi-130903', '북촌문화센터', '주변 한옥 카페들이랑 묶어서 하루 코스로 다녀오기 정말 좋아요. 사진 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 5, '["전통차", "카페투어", "데이트", "먹거리"]'::jsonb, 37.579053, 126.986706, '2026-10-12T10:41:17Z'::timestamptz),
('54500700-0000-4000-9000-000000000003', '54500700-0000-4000-8000-000000000008', 'p-tourapi-1883087', '연우하우스', '''연우하우스'' 처음 와봤는데, 바람 불 때마다 풍경 소리 딸랑거리는 게 너무 좋았어요. 머릿속 복잡할 때 혼자 산책 오기 딱입니다.', '한적', 5, '["고즈넉", "힐링", "혼자여행", "조용한", "온마루"]'::jsonb, 37.582281, 126.985312, '2026-10-12T07:36:17Z'::timestamptz),
('54500700-0000-4000-9000-000000000004', '54500700-0000-4000-8000-000000000005', 'p-tourapi-2000648', '하회 북촌댁', '''하회 북촌댁'' 처음 와봤는데, 산책 한 바퀴 돌고 바로 근처 한옥 찻집에서 오미자차 한 잔 마시니까 코스가 딱 완벽하네요. 주말 데이트 강추!', '북적', 5, '["전통차", "카페투어", "데이트", "먹거리", "온마루"]'::jsonb, 36.539740, 128.517876, '2026-10-12T11:25:17Z'::timestamptz),
('54500700-0000-4000-9000-000000000005', '54500700-0000-4000-8000-000000000032', 'p-tourapi-2373420', '아띠인력거', '이번 여행 코스로 아띠인력거 넣길 정말 잘했어요. 아침 일찍 개방 시간 맞춰서 갔더니 발소리만 사박사박 들려요. 복잡한 도시 벗어나서 힐링 제대로 하고 옴.', '한적', 5, '["고즈넉", "힐링", "혼자여행", "조용한", "온마루"]'::jsonb, 37.579389, 126.982559, '2026-10-12T08:59:17Z'::timestamptz),
('54500700-0000-4000-9000-000000000006', '54500700-0000-4000-8000-000000000027', 'p-tourapi-2481866', '백인제가옥', '오랜만에 백인제가옥 들렀는데 일부러 연차 쓰고 평일 오전에 왔더니 진짜 조용하고 평화롭네요. 마루에 가만히 앉아만 있어도 힐링됨.', '한적', 5, '["고즈넉", "힐링", "혼자여행", "조용한", "온마루"]'::jsonb, 37.580469, 126.984142, '2026-10-12T11:01:17Z'::timestamptz),
('54500700-0000-4000-9000-000000000007', '54500700-0000-4000-8000-000000000004', 'p-tourapi-2575836', '북촌 게스트하우스', '북촌 게스트하우스 둘러보고 왔어요. 산책 한 바퀴 돌고 바로 근처 한옥 찻집에서 오미자차 한 잔 마시니까 코스가 딱 완벽하네요. 주말 데이트 강추!', '북적', 5, '["전통차", "카페투어", "데이트", "먹거리", "온마루"]'::jsonb, 37.578628, 126.985681, '2026-10-12T15:12:17Z'::timestamptz),
('54500700-0000-4000-9000-000000000008', '54500700-0000-4000-8000-000000000029', 'p-tourapi-2607481', '향운', '오랜만에 향운 들렀는데 혼자 조용히 사색하기에 이만한 곳이 없어요. 마루 끝에 걸터앉아서 새소리 듣는 시간이 제일 행복했음.', '한적', 4, '["고즈넉", "힐링", "혼자여행", "조용한", "온마루"]'::jsonb, 37.583027, 126.985925, '2026-10-12T12:48:17Z'::timestamptz),
('54500700-0000-4000-9000-000000000009', '54500700-0000-4000-8000-000000000007', 'p-tourapi-2608499', '미담 한옥 게스트 하우스', '주말에 친구들이랑 한복 대여해서 갔는데 골목길 채광이 사기예요 ㅋㅋㅋ 사람 많아도 사진은 다 건졌음!', '북적', 4, '["사진맛집", "데이트", "주말나들이"]'::jsonb, 37.580664, 126.986353, '2026-10-12T15:28:17Z'::timestamptz),
('54500700-0000-4000-9000-000000000010', '54500700-0000-4000-8000-000000000011', 'p-tourapi-2696383', '한옥 201(Hanok 201)', '아이들이랑 같이 방문했는데 책에서만 보던 전통 가옥 직접 만져보고 걸어볼 수 있어서 교육적으로도 참 유익했네요.', '한적', 4, '["부모님과", "가족여행", "역사체험", "고택", "온마루"]'::jsonb, 37.580558, 126.985414, '2026-10-12T10:13:17Z'::timestamptz),
('54500700-0000-4000-9000-000000000011', '54500700-0000-4000-8000-000000000001', 'p-tourapi-2992824', '락고재 컬쳐 라운지 애가헌', '해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이나 디테일들이 다 다르게 보여요. 꼭 설명 들어보세요!', '한적', 5, '["부모님과", "가족여행", "역사체험", "고택"]'::jsonb, 37.582243, 126.983944, '2026-10-12T09:18:17Z'::timestamptz),
('54500700-0000-4000-9000-000000000012', '54500700-0000-4000-8000-000000000032', 'p-tourapi-3072219', '북촌빈관 by 락고재', '''북촌빈관 by 락고재'' 처음 와봤는데, 바람 불 때마다 풍경 소리 딸랑거리는 게 너무 좋았어요. 머릿속 복잡할 때 혼자 산책 오기 딱입니다.', '한적', 5, '["고즈넉", "힐링", "혼자여행", "조용한", "온마루"]'::jsonb, 37.582347, 126.984220, '2026-10-12T07:48:17Z'::timestamptz),
('54500700-0000-4000-9000-000000000013', '54500700-0000-4000-8000-000000000004', 'p-tourapi-3085314', '북촌전통발효공방 빚담', '인기 포토존은 줄 좀 서야 하지만 회전율은 빨라요. 마당 구석 정자 쪽이 숨은 포토스팟입니다 다들 잘 모르더라구요!', '북적', 5, '["방문팁", "데이트", "산책"]'::jsonb, 37.582349, 126.985501, '2026-10-12T08:00:17Z'::timestamptz),
('54500700-0000-4000-9000-000000000014', '54500700-0000-4000-8000-000000000006', 'p-tourapi-3102210', '선음재', '''선음재'' 처음 와봤는데, 마당에 심어진 소나무랑 담장 너머 하늘 조화가 기가 막힙니다. 가을 단풍 들 때 무조건 다시 올 거예요.', '한적', 5, '["풍경맛집", "계절감", "산책로", "고즈넉"]'::jsonb, 37.585097, 126.985631, '2026-10-12T13:03:17Z'::timestamptz),
('54500700-0000-4000-9000-000000000015', '54500700-0000-4000-8000-000000000016', 'p-tourapi-3438082', '안길사가', '''안길사가'' 처음 와봤는데, 여름엔 모기기피제 살짝 챙기면 좋음 ㅎㅎ 그래도 마루에 불어오는 바람이 에어컨 바람보다 훨씬 상쾌하네요.', '북적', 5, '["방문팁", "데이트", "산책"]'::jsonb, 37.577486, 126.984503, '2026-10-12T09:54:17Z'::timestamptz),
('54500700-0000-4000-9000-000000000016', '54500700-0000-4000-8000-000000000021', 'p-tourapi-3438368', '해아원', '비 오는 날 한옥은 진짜 치트키네요. 흙냄새랑 젖은 나무 냄새가 묘하게 마음을 편하게 해줘요.', '한적', 5, '["비오는날", "고즈넉", "비멍", "분위기맛집", "온마루"]'::jsonb, 37.582897, 126.983320, '2026-10-12T11:42:17Z'::timestamptz),
('54500700-0000-4000-9000-000000000017', '54500700-0000-4000-8000-000000000020', 'p-tourapi-3438381', '북촌다락방', '해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이나 디테일들이 다 다르게 보여요. 꼭 설명 들어보세요!', '한적', 5, '["부모님과", "가족여행", "역사체험", "고택"]'::jsonb, 37.582780, 126.983926, '2026-10-12T15:49:17Z'::timestamptz),
('54500700-0000-4000-9000-000000000018', '54500700-0000-4000-8000-000000000007', 'p-tourapi-3438735', '소월담', '소월담 둘러보고 왔어요. 주말에 친구들이랑 한복 대여해서 갔는데 골목길 채광이 사기예요 ㅋㅋㅋ 사람 많아도 사진은 다 건졌음!', '북적', 4, '["사진맛집", "데이트", "주말나들이"]'::jsonb, 37.578825, 126.985898, '2026-10-12T14:48:17Z'::timestamptz),
('54500700-0000-4000-9000-000000000019', '54500700-0000-4000-8000-000000000016', 'p-tourapi-3533161', '앙니드 공이안', '이번 여행 코스로 앙니드 공이안 넣길 정말 잘했어요. 비 와서 갈까 말까 고민했는데 안 왔으면 후회할 뻔! 빗소리 들으면서 마루에 앉아있으니 운치 최고예요.', '한적', 5, '["비오는날", "고즈넉", "비멍", "분위기맛집"]'::jsonb, 37.581633, 126.981493, '2026-10-12T11:54:17Z'::timestamptz),
('54500700-0000-4000-9000-000000000020', '54500700-0000-4000-8000-000000000034', 'p-tourapi-3582693', '한복남 북촌점', '''한복남 북촌점'' 처음 와봤는데, 주말에 친구들이랑 한복 대여해서 갔는데 골목길 채광이 사기예요 ㅋㅋㅋ 사람 많아도 사진은 다 건졌음!', '북적', 5, '["사진맛집", "데이트", "주말나들이"]'::jsonb, 37.579845, 126.984742, '2026-10-12T14:46:17Z'::timestamptz),
('54500700-0000-4000-9000-000000000021', '54500700-0000-4000-8000-000000000010', 'p-tourapi-264353', '인사동', '비 와서 갈까 말까 고민했는데 안 왔으면 후회할 뻔! 빗소리 들으면서 마루에 앉아있으니 운치 최고예요.', '한적', 5, '["비오는날", "고즈넉", "비멍", "분위기맛집"]'::jsonb, 37.575462, 126.983523, '2026-10-12T11:12:17Z'::timestamptz),
('54500700-0000-4000-9000-000000000022', '54500700-0000-4000-8000-000000000017', 'p-tourapi-3072072', '한옥에세이 서촌', '''한옥에세이 서촌'' 처음 와봤는데, 인기 포토존은 줄 좀 서야 하지만 회전율은 빨라요. 마당 구석 정자 쪽이 숨은 포토스팟입니다 다들 잘 모르더라구요!', '북적', 5, '["방문팁", "데이트", "산책"]'::jsonb, 37.578669, 126.968397, '2026-10-12T15:29:17Z'::timestamptz),
('54500700-0000-4000-9000-000000000023', '54500700-0000-4000-8000-000000000003', 'p-tourapi-2660696', '세연재', '생각보다 사람 많아서 놀랐는데 구석구석 포토존이 진짜 많네요. 오후 4시쯤 노을 질 때 강추!', '북적', 5, '["사진맛집", "데이트", "주말나들이", "온마루"]'::jsonb, 37.640328, 126.939534, '2026-10-12T12:35:17Z'::timestamptz),
('54500700-0000-4000-9000-000000000024', '54500700-0000-4000-8000-000000000028', 'p-tourapi-2676000', '응정헌', '역시 소문대로 응정헌 분위기 좋네요! 주차는 근처 공영주차장 이용하는 게 정신건강에 좋습니다 ㅋㅋㅋ 골목 안쪽은 차 절대 못 들어가요! 그래도 뷰는 최고.', '북적', 5, '["방문팁", "데이트", "산책", "온마루"]'::jsonb, 37.640298, 126.939686, '2026-10-12T07:45:17Z'::timestamptz),
('54500700-0000-4000-9000-000000000025', '54500700-0000-4000-8000-000000000010', 'p-tourapi-2679044', '청향재', '청향재 둘러보고 왔어요. 대청마루랑 마당 구조가 옛 선조들 지혜가 고스란히 묻어있네요. 어르신들 모시고 오기 정말 훌륭한 장소입니다.', '한적', 4, '["부모님과", "가족여행", "역사체험", "고택", "온마루"]'::jsonb, 37.641706, 126.940197, '2026-10-12T16:23:17Z'::timestamptz),
('54500700-0000-4000-9000-000000000026', '54500700-0000-4000-8000-000000000016', 'p-tourapi-2724392', '은평한옥마을', '산책 한 바퀴 돌고 바로 근처 한옥 찻집에서 오미자차 한 잔 마시니까 코스가 딱 완벽하네요. 주말 데이트 강추!', '북적', 4, '["전통차", "카페투어", "데이트", "먹거리", "온마루"]'::jsonb, 37.641395, 126.939225, '2026-10-12T07:30:17Z'::timestamptz),
('54500700-0000-4000-9000-000000000027', '54500700-0000-4000-8000-000000000010', 'p-tourapi-2764323', '은평역사한옥박물관', '바람 불 때마다 풍경 소리 딸랑거리는 게 너무 좋았어요. 머릿속 복잡할 때 혼자 산책 오기 딱입니다.', '한적', 4, '["고즈넉", "힐링", "혼자여행", "조용한", "온마루"]'::jsonb, 37.640334, 126.938008, '2026-10-12T14:02:17Z'::timestamptz),
('54500700-0000-4000-9000-000000000028', '54500700-0000-4000-8000-000000000022', 'p-tourapi-3438435', '사임당 귀한그대', '처마 끝 곡선 뒤로 푸른 산이 병풍처럼 둘러싸고 있는 풍경이 압권입니다. 눈이 맑아지는 기분이에요.', '한적', 5, '["풍경맛집", "계절감", "산책로", "고즈넉"]'::jsonb, 37.641234, 126.940136, '2026-10-12T12:49:17Z'::timestamptz),
('54500700-0000-4000-9000-000000000029', '54500700-0000-4000-8000-000000000007', 'p-tourapi-3438450', '평안채', '부모님 모시고 효도 관광으로 다녀왔는데 두 분 다 너무 좋아하셔서 뿌듯했습니다. 나무 기둥 결 하나하나 멋스러워요.', '한적', 5, '["부모님과", "가족여행", "역사체험", "고택"]'::jsonb, 37.640873, 126.938714, '2026-10-12T13:16:17Z'::timestamptz),
('54500700-0000-4000-9000-000000000030', '54500700-0000-4000-8000-000000000023', 'p-tourapi-3438452', '담서제', '역시 소문대로 담서제 분위기 좋네요! 비 오는 날 한옥은 진짜 치트키네요. 흙냄새랑 젖은 나무 냄새가 묘하게 마음을 편하게 해줘요.', '한적', 5, '["비오는날", "고즈넉", "비멍", "분위기맛집"]'::jsonb, 37.640531, 126.939267, '2026-10-12T10:15:17Z'::timestamptz),
('54500700-0000-4000-9000-000000000031', '54500700-0000-4000-8000-000000000018', 'p-tourapi-3438468', '생활서가', '흐린 날씨라 사람도 별로 없고 운치 대박이었어요. 따뜻한 차 한 잔 마시면서 밖 바라보는데 영화 속 한 장면 같음.', '한적', 5, '["비오는날", "고즈넉", "비멍", "분위기맛집", "온마루"]'::jsonb, 37.642950, 126.939222, '2026-10-12T07:54:17Z'::timestamptz),
('54500700-0000-4000-9000-000000000032', '54500700-0000-4000-8000-000000000017', 'p-tourapi-3438470', '한옥 카키', '아침 일찍 개방 시간 맞춰서 갔더니 발소리만 사박사박 들려요. 복잡한 도시 벗어나서 힐링 제대로 하고 옴.', '한적', 5, '["고즈넉", "힐링", "혼자여행", "조용한"]'::jsonb, 37.642397, 126.939164, '2026-10-12T12:32:17Z'::timestamptz),
('54500700-0000-4000-9000-000000000033', '54500700-0000-4000-8000-000000000023', 'p-tourapi-3438485', '다락재', '주변 한옥 카페들이랑 묶어서 하루 코스로 다녀오기 정말 좋아요. 사진 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 5, '["전통차", "카페투어", "데이트", "먹거리"]'::jsonb, 37.641231, 126.939842, '2026-10-12T08:20:17Z'::timestamptz),
('54500700-0000-4000-9000-000000000034', '54500700-0000-4000-8000-000000000013', 'p-tourapi-3438494', '상상헌', '마침 비가 부슬부슬 내리는 날 갔는데 처마에서 빗방울 떨어지는 소리가 예술입니다... 비멍 때리다 시간 다 감.', '한적', 5, '["비오는날", "고즈넉", "비멍", "분위기맛집"]'::jsonb, 37.641609, 126.938603, '2026-10-12T17:02:17Z'::timestamptz),
('54500700-0000-4000-9000-000000000035', '54500700-0000-4000-8000-000000000013', 'p-tourapi-3438496', '소우주', '소우주 둘러보고 왔어요. 흐린 날씨라 사람도 별로 없고 운치 대박이었어요. 따뜻한 차 한 잔 마시면서 밖 바라보는데 영화 속 한 장면 같음.', '한적', 5, '["비오는날", "고즈넉", "비멍", "분위기맛집", "온마루"]'::jsonb, 37.640970, 126.938620, '2026-10-12T11:42:17Z'::timestamptz),
('54500700-0000-4000-9000-000000000036', '54500700-0000-4000-8000-000000000020', 'p-tourapi-3438504', '한옥 포지티브스', '낮 12시~2시는 햇빛이 꽤 강하니까 양산이나 모자 챙기세요. 해 질 녘 골목에 가로등 켜질 때가 진짜 낭만임.', '북적', 5, '["방문팁", "데이트", "산책", "온마루"]'::jsonb, 37.641678, 126.939414, '2026-10-12T11:29:17Z'::timestamptz),
('54500700-0000-4000-9000-000000000037', '54500700-0000-4000-8000-000000000009', 'p-tourapi-3438527', '한울타리', '혼자 조용히 사색하기에 이만한 곳이 없어요. 마루 끝에 걸터앉아서 새소리 듣는 시간이 제일 행복했음.', '한적', 5, '["고즈넉", "힐링", "혼자여행", "조용한"]'::jsonb, 37.641464, 126.939292, '2026-10-12T10:35:17Z'::timestamptz),
('54500700-0000-4000-9000-000000000038', '54500700-0000-4000-8000-000000000020', 'p-tourapi-3438545', '예맥당 한옥스테이', '역시 소문대로 예맥당 한옥스테이 분위기 좋네요! 부모님 모시고 효도 관광으로 다녀왔는데 두 분 다 너무 좋아하셔서 뿌듯했습니다. 나무 기둥 결 하나하나 멋스러워요.', '한적', 4, '["부모님과", "가족여행", "역사체험", "고택"]'::jsonb, 37.640767, 126.938895, '2026-10-12T09:43:17Z'::timestamptz),
('54500700-0000-4000-9000-000000000039', '54500700-0000-4000-8000-000000000021', 'p-tourapi-126747', '남산골한옥마을', '아이들이랑 같이 방문했는데 책에서만 보던 전통 가옥 직접 만져보고 걸어볼 수 있어서 교육적으로도 참 유익했네요.', '한적', 5, '["부모님과", "가족여행", "역사체험", "고택"]'::jsonb, 37.559778, 126.993287, '2026-10-12T13:25:17Z'::timestamptz),
('54500700-0000-4000-9000-000000000040', '54500700-0000-4000-8000-000000000011', 'p-tourapi-2569237', '운정루', '이번 여행 코스로 운정루 넣길 정말 잘했어요. 산책 한 바퀴 돌고 바로 근처 한옥 찻집에서 오미자차 한 잔 마시니까 코스가 딱 완벽하네요. 주말 데이트 강추!', '북적', 5, '["전통차", "카페투어", "데이트", "먹거리"]'::jsonb, 35.791283, 129.245897, '2026-10-12T11:20:17Z'::timestamptz),
('54500700-0000-4000-9000-000000000041', '54500700-0000-4000-8000-000000000016', 'p-tourapi-2605809', '태화강동굴피아', '역시 소문대로 태화강동굴피아 분위기 좋네요! 주변 한옥 카페들이랑 묶어서 하루 코스로 다녀오기 정말 좋아요. 사진 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 5, '["전통차", "카페투어", "데이트", "먹거리"]'::jsonb, 35.545284, 129.302468, '2026-10-09T02:17:17Z'::timestamptz),
('54500700-0000-4000-9000-000000000042', '54500700-0000-4000-8000-000000000005', 'p-tourapi-2701396', '서남산한옥', '아이들이랑 같이 방문했는데 책에서만 보던 전통 가옥 직접 만져보고 걸어볼 수 있어서 교육적으로도 참 유익했네요.', '한적', 5, '["부모님과", "가족여행", "역사체험", "고택", "온마루"]'::jsonb, 35.780864, 129.204559, '2026-09-29T23:06:17Z'::timestamptz),
('54500700-0000-4000-9000-000000000043', '54500700-0000-4000-8000-000000000026', 'p-tourapi-126387', '전주 풍패지관 (전주객사)', '바람 불 때마다 풍경 소리 딸랑거리는 게 너무 좋았어요. 머릿속 복잡할 때 혼자 산책 오기 딱입니다.', '한적', 4, '["고즈넉", "힐링", "혼자여행", "조용한"]'::jsonb, 35.818500, 127.145400, '2026-10-12T02:21:17Z'::timestamptz),
('54500700-0000-4000-9000-000000000044', '54500700-0000-4000-8000-000000000007', 'p-tourapi-129030', '전주유씨 무실종택', '이번 여행 코스로 전주유씨 무실종택 넣길 정말 잘했어요. 처마 끝 곡선 뒤로 푸른 산이 병풍처럼 둘러싸고 있는 풍경이 압권입니다. 눈이 맑아지는 기분이에요.', '한적', 5, '["풍경맛집", "계절감", "산책로", "고즈넉"]'::jsonb, 36.553440, 128.923692, '2026-10-02T08:15:17Z'::timestamptz),
('54500700-0000-4000-9000-000000000045', '54500700-0000-4000-8000-000000000008', 'p-tourapi-1594374', '전주전통한지원', '대청마루랑 마당 구조가 옛 선조들 지혜가 고스란히 묻어있네요. 어르신들 모시고 오기 정말 훌륭한 장소입니다.', '한적', 5, '["부모님과", "가족여행", "역사체험", "고택"]'::jsonb, 35.815995, 127.153533, '2026-09-30T21:43:17Z'::timestamptz),
('54500700-0000-4000-9000-000000000046', '54500700-0000-4000-8000-000000000029', 'p-tourapi-1594500', '전주목판서화체험관', '여름엔 모기기피제 살짝 챙기면 좋음 ㅎㅎ 그래도 마루에 불어오는 바람이 에어컨 바람보다 훨씬 상쾌하네요.', '북적', 4, '["방문팁", "데이트", "산책"]'::jsonb, 35.811515, 127.155650, '2026-09-30T12:50:17Z'::timestamptz),
('54500700-0000-4000-9000-000000000047', '54500700-0000-4000-8000-000000000031', 'p-tourapi-1594746', '장현식고택', '해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이나 디테일들이 다 다르게 보여요. 꼭 설명 들어보세요!', '한적', 4, '["부모님과", "가족여행", "역사체험", "고택", "온마루"]'::jsonb, 35.812156, 127.156492, '2026-10-06T07:29:17Z'::timestamptz),
('54500700-0000-4000-9000-000000000048', '54500700-0000-4000-8000-000000000016', 'p-tourapi-1871362', '문화공간 양사재', '문화공간 양사재 둘러보고 왔어요. 흐린 날씨라 사람도 별로 없고 운치 대박이었어요. 따뜻한 차 한 잔 마시면서 밖 바라보는데 영화 속 한 장면 같음.', '한적', 5, '["비오는날", "고즈넉", "비멍", "분위기맛집"]'::jsonb, 35.813145, 127.154136, '2026-10-07T05:01:17Z'::timestamptz),
('54500700-0000-4000-9000-000000000049', '54500700-0000-4000-8000-000000000006', 'p-tourapi-1882371', '학인당', '역시 소문대로 학인당 분위기 좋네요! 바람 불 때마다 풍경 소리 딸랑거리는 게 너무 좋았어요. 머릿속 복잡할 때 혼자 산책 오기 딱입니다.', '한적', 5, '["고즈넉", "힐링", "혼자여행", "조용한", "온마루"]'::jsonb, 35.811812, 127.152057, '2026-10-07T16:14:17Z'::timestamptz),
('54500700-0000-4000-9000-000000000050', '54500700-0000-4000-8000-000000000030', 'p-tourapi-1882853', '풍남헌', '오랜만에 풍남헌 들렀는데 부모님 모시고 효도 관광으로 다녀왔는데 두 분 다 너무 좋아하셔서 뿌듯했습니다. 나무 기둥 결 하나하나 멋스러워요.', '한적', 4, '["부모님과", "가족여행", "역사체험", "고택"]'::jsonb, 35.816784, 127.152314, '2026-10-03T21:21:17Z'::timestamptz),
('54500700-0000-4000-9000-000000000051', '54500700-0000-4000-8000-000000000002', 'p-tourapi-1883085', '늘봄스테이', '초록초록한 마당 정원이랑 한옥 색감이 너무 잘 어울려요. 툇마루에서 바람 쐬고 있으면 잡생각이 다 날아갑니다.', '한적', 5, '["풍경맛집", "계절감", "산책로", "고즈넉", "온마루"]'::jsonb, 35.813289, 127.152181, '2026-10-12T01:56:17Z'::timestamptz),
('54500700-0000-4000-9000-000000000052', '54500700-0000-4000-8000-000000000027', 'p-tourapi-1971880', '좋은날', '여름엔 모기기피제 살짝 챙기면 좋음 ㅎㅎ 그래도 마루에 불어오는 바람이 에어컨 바람보다 훨씬 상쾌하네요.', '북적', 5, '["방문팁", "데이트", "산책", "온마루"]'::jsonb, 35.817283, 127.149292, '2026-10-07T12:47:17Z'::timestamptz),
('54500700-0000-4000-9000-000000000053', '54500700-0000-4000-8000-000000000002', 'p-tourapi-1972014', '삼락헌', '해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이나 디테일들이 다 다르게 보여요. 꼭 설명 들어보세요!', '한적', 5, '["부모님과", "가족여행", "역사체험", "고택", "온마루"]'::jsonb, 35.815648, 127.152720, '2026-10-03T13:32:17Z'::timestamptz),
('54500700-0000-4000-9000-000000000054', '54500700-0000-4000-8000-000000000009', 'p-tourapi-1972381', '서로', '오랜만에 서로 들렀는데 여름엔 모기기피제 살짝 챙기면 좋음 ㅎㅎ 그래도 마루에 불어오는 바람이 에어컨 바람보다 훨씬 상쾌하네요.', '북적', 5, '["방문팁", "데이트", "산책", "온마루"]'::jsonb, 35.815775, 127.153606, '2026-09-29T13:42:17Z'::timestamptz),
